import sys
sys.setrecursionlimit(10 ** 6)

def calc_colors(nodes, x, colors, exp_color, parent):
	total_value = 0
	total_value1 = 0
	if exp_color == '1':
		val = 1
		next_exp = '0'
	else:
		val = -1
		next_exp = '1'
	if colors[x] != exp_color:
		total_value = val
	else:
		total_value1 = val
	total_dist = 0
	total_dist1 = 0
	for i in nodes[x]:
		if i == parent:
			continue
		(dist, val, dist1, val1) = calc_colors(nodes, i, colors, next_exp, x)
		total_dist += dist
		total_value += val
		total_dist1 += dist1
		total_value1 += val1
	total_dist += abs(total_value)
	total_dist1 += abs(total_value1)
	return (total_dist, total_value, total_dist1, total_value1)

def solve() -> None:
	n = int(input())
	nodes = []
	for i in range(n):
		nodes.append([])
	for i in range(n - 1):
		(u, v) = tuple(map(int, input().split()))
		nodes[u - 1].append(v - 1)
		nodes[v - 1].append(u - 1)
	colors = input()
	(dist1, val1, dist2, val2) = calc_colors(nodes, 0, colors, '0', 0)
	if val1 != 0 != val2:
		print(-1)
	elif val1 == 0 == val2:
		if dist1 > dist2:
			print(dist2)
		else:
			print(dist1)
	elif val1 == 0:
		print(dist1)
	else:
		print(dist2)
t = int(input())
for i in range(t):
	try:
		solve()
	except RecursionError:
		print('recursionerror')
